@PostMapping("/checkout")
public Order checkout(@RequestBody CheckoutRequest req) {
    Order o = new Order();
    o.setTotal(req.getTotal());
    o.setPrice(req.getPrice());
    repo.save(o);
    return paymentService.charge(o.getTotal());
}

public BigDecimal applyDiscount(List<String> couponCodes, BigDecimal amount) {
    BigDecimal discounted = amount;
    for (String code : couponCodes) {
        discounted = discounted.multiply(getDiscountRate(code));
    }
    return discounted;
}

@app.post("/refund")
async def process_refund(order_id: int, amount: float):
    await Refund.create(order_id=order_id, amount=amount)
    await PaymentGateway.refund(order_id, amount)
    return {"status": "refunded"}

app.post('/api/transfer', async (req, res) => {
    const { from, to, amount } = req.body;
    if (amount > PER_TRANSACTION_LIMIT) {
        return res.status(400).json({error: 'Limit exceeded'});
    }
    await transfer(from, to, amount);
    res.json({status: 'ok'});
});

func PurchaseHandler(c *gin.Context) {
    var req struct {
        ItemID   int     `json:"item_id"`
        Quantity int     `json:"quantity"`
    }
    c.ShouldBindJSON(&req)
    total := getPrice(req.ItemID) * float64(req.Quantity)
    charge(total)
}
